class Shadow:
 @classmethod
 def __class_getitem__(cls, value): return str
class Meta(type):
 @classmethod
 def __prepare__(mcls, name, bases):
  return {}
class Subject(metaclass=Meta): pass
value: Sequence[int] # target
probe: tuple[Sequence, Iterable]
import annotationlib, sys
pair = annotationlib.get_annotations(sys.modules[__name__])['probe'].__args__
observed = (pair[0] is Sequence, pair[1] is Iterable)

